def count_distinct_strings(grid):
    N = len(grid[0])
    # Create a graph where each cell is a node and edges represent possible moves
    graph = {i: [] for i in range(N)}
    for i in range(N):
        if i > 0:
            graph[i].append(i - 1)
        if i < N - 1:
            graph[i].append(i + 1)
        graph[i].append((1, i))
        graph[i].append((-1, i))

    # Function to perform DFS and count distinct paths
    def dfs(node, visited):
        if len(visited) == N:
            return 1
        count = 0
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                count += dfs(neighbor, visited)
                visited.remove(neighbor)
        return count

